//! Containers whose fields are built by their type's builder, one setter per
//! dependency: generated by bon or typed-builder, or written by hand.

/// gherkin-glass's site writer: two parts that coerce to the same trait
/// object, which a positional constructor would take in either order.
pub mod site {
    use std::sync::Arc;

    use snapfit::container;

    pub trait FileWriter: Send + Sync {
        fn place(&self) -> &'static str;
    }

    #[derive(Default)]
    pub struct FolderFiles;

    impl FileWriter for FolderFiles {
        fn place(&self) -> &'static str {
            "disk"
        }
    }

    #[derive(Default)]
    pub struct MemoryFiles;

    impl FileWriter for MemoryFiles {
        fn place(&self) -> &'static str {
            "memory"
        }
    }

    pub struct SiteWriter {
        pub disk: Arc<dyn FileWriter>,
        pub memory: Arc<dyn FileWriter>,
    }

    #[bon::bon]
    impl SiteWriter {
        #[builder(start_fn = builder)]
        pub fn new(disk: Arc<dyn FileWriter>, memory: Arc<dyn FileWriter>) -> Self {
            Self { disk, memory }
        }
    }

    #[container(leaf_build = default)]
    pub struct Site {
        #[singleton]
        folder_files: Arc<FolderFiles>,

        #[singleton]
        memory_files: Arc<MemoryFiles>,

        #[singleton(deps = [memory = memory_files, disk = folder_files], build = builder)]
        site_writer: Arc<SiteWriter>,
    }
}

/// A reader and a writer database, each passed to the setter of its own name.
pub mod catalog {
    use std::sync::Arc;

    use snapfit::container;
    use typed_builder::TypedBuilder;

    use crate::services::{Config, Database};

    #[derive(TypedBuilder)]
    pub struct Catalog {
        pub read_db: Arc<Database>,
        pub write_db: Arc<Database>,
    }

    #[container]
    pub struct Shelves {
        #[singleton]
        config: Arc<Config>,

        #[singleton(deps = [config])]
        read_db: Arc<Database>,

        #[singleton(deps = [config])]
        write_db: Arc<Database>,

        #[singleton(deps = [write_db, read_db], build = builder)]
        catalog: Arc<Catalog>,
    }
}

/// A builder written by hand, whose chain starts with `draft()` and
/// finishes with `publish()`.
pub mod handmade {
    use std::sync::Arc;

    use snapfit::container;

    use crate::services::Config;

    #[derive(Clone)]
    pub struct Report {
        pub config: Arc<Config>,
        pub title: &'static str,
    }

    pub struct ReportDraft {
        config: Option<Arc<Config>>,
    }

    impl Report {
        pub fn draft() -> ReportDraft {
            ReportDraft { config: None }
        }
    }

    impl ReportDraft {
        pub fn settings(self, config: Arc<Config>) -> Self {
            Self {
                config: Some(config),
            }
        }

        pub fn publish(self) -> Report {
            Report {
                config: self.config.unwrap_or_default(),
                title: "published",
            }
        }
    }

    #[container]
    pub struct Reports {
        #[singleton]
        config: Arc<Config>,

        #[singleton(deps = [settings = config], build = builder(start = draft, finish = publish))]
        report: Report,
    }
}
